// No registrar cuerpo, cabeceras ni binarios en logs.
const crypto = require('crypto');
const input = $input.first();
const b = input.json.body;
const invalid = () => [{json:{valid:false}}];
if (!b || typeof b !== 'object' || Array.isArray(b)) return invalid();
const fields = ['protocol_version','email','partido','partido_id','tipo','idempotency_key','recurso_id','tipo_recurso','pdf_sha256','pdf_bytes'];
if (Object.keys(b).length !== fields.length || fields.some(k => typeof b[k] !== 'string')) return invalid();
if (b.protocol_version !== '1' || !/^[a-f0-9]{64}$/.test(b.idempotency_key) || !/^[a-f0-9]{64}$/.test(b.pdf_sha256)) return invalid();
if (!['abono','parking'].includes(b.tipo_recurso) || b.tipo !== (b.tipo_recurso === 'abono' ? 'entrada' : 'parking')) return invalid();
if (![b.partido_id,b.recurso_id].every(v=>/^[1-9][0-9]{0,9}$/.test(v))) return invalid();
if (b.email.length > 254 || !/^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?\.[A-Za-z]{2,}$/.test(b.email)) return invalid();
if (!b.partido.length || b.partido.length>200 || /[\x00-\x1f\x7f]/.test(b.partido)) return invalid();
if (!/^[1-9][0-9]{0,7}$/.test(b.pdf_bytes)) return invalid();
if (!input.binary || Object.keys(input.binary).length !== 1 || !input.binary.pdf) return invalid();
const pdf = input.binary.pdf;
if (pdf.mimeType !== 'application/pdf' || typeof pdf.fileName !== 'string' || pdf.fileName.length>255 || /[\x00-\x1f\x7f\\/]/.test(pdf.fileName) || !/\.pdf$/i.test(pdf.fileName)) return invalid();
const buffer = await this.helpers.getBinaryDataBuffer(0,'pdf');
if (!buffer.length || buffer.length>5*1024*1024 || buffer.length!==Number(b.pdf_bytes)) return invalid();
if (buffer.subarray(0,5).toString() !== '%PDF-' || !buffer.subarray(-4096).includes(Buffer.from('%%EOF'))) return invalid();
if (crypto.createHash('sha256').update(buffer).digest('hex') !== b.pdf_sha256) return invalid();
const lower = buffer.toString('latin1').toLowerCase();
if (['/javascript','/js','/launch','/openaction','/embeddedfile','/richmedia','/xfa'].some(marker=>lower.includes(marker))) return invalid();
const body = Object.fromEntries(fields.map(k=>[k,b[k]]));
const payload_hash = crypto.createHash('sha256').update(JSON.stringify(fields.map(k=>body[k]))).digest('hex');
return [{json:{valid:true,body,payload_hash,owner_token:crypto.randomUUID()},binary:{pdf}}];

const source = $('Validar solicitud').first();
const receipt = $input.first().json;
const same = receipt.payload_hash === source.json.payload_hash;
const send = same && receipt.state === 'processing' && receipt.owner_token === source.json.owner_token;
if (send) return [{json:{...source.json,send:true},binary:source.binary}];
const confirmed = same && receipt.state === 'sent';
return [{json:{send:false,http_status:confirmed?200:409,reply:confirmed?
 {ok:true,protocol_version:'1',status:'sent',idempotency_key:source.json.body.idempotency_key,pdf_sha256:source.json.body.pdf_sha256}:
 {ok:false,code:'REVIEW_REQUIRED'}}}];

const result = $input.first().json;
const destination = $('Validar solicitud').first().json.body.email.toLowerCase();
if (!Array.isArray(result.accepted) || !result.accepted.some(v=>typeof v==='string' && v.toLowerCase()===destination) || (Array.isArray(result.rejected) && result.rejected.length)) {
  throw new Error('SMTP no ha confirmado el destinatario. Revisar registro; no repetir automaticamente.');
}
return [{json:{confirmed:true}}];
